# this_file: tools/legacy_template.py
"""Lazy legacy aliases for the issue-205 domain layout (generated by restructure).

Ordinary aliases use Python's import hooks and share canonical module identity.
Six old modules also name domain packages: these packages lazily forward model
attributes while keeping normal, separate package and implementation modules.
No child, native API or Qt binding is imported merely to install the hook.
"""

import importlib
import importlib.abc
import importlib.machinery
import importlib.util
import sys
from types import ModuleType

ALIASES = {}  # ALIAS_TABLE


class _AliasLoader(importlib.abc.Loader):
    """Return the canonical object without executing its source a second time."""

    def __init__(self, target: str) -> None:
        self.target = target

    def create_module(self, spec: importlib.machinery.ModuleSpec) -> ModuleType:
        module = importlib.import_module(self.target)
        self.canonical_spec = getattr(module, "__spec__", None)
        return module

    def exec_module(self, module: ModuleType) -> None:
        # importlib sets __spec__ for the alias; retain canonical reload/pickle metadata.
        module.__spec__ = self.canonical_spec


class _Facade(ModuleType):
    """Forward model attributes without changing either module's identity."""

    def __getattribute__(self, name: str) -> object:
        namespace = ModuleType.__getattribute__(self, "__dict__")
        if name == "__dict__":
            # Patch tools inspect the real dict to save originals for undo.
            model = _facade_model(self)
            for exported in namespace.get("_legacy_exports", ()):
                namespace.pop(exported, None)
            exports = {
                key: value for key, value in vars(model).items()
                if not key.startswith("__") and key not in namespace
            }
            namespace.update(exports)
            namespace["_legacy_exports"] = exports.keys()
            return namespace
        if name in namespace.get("_legacy_exports", ()):
            return getattr(_facade_model(self), name)
        return super().__getattribute__(name)

    def __getattr__(self, name: str) -> object:
        if name.startswith("__") and name != "__all__":
            raise AttributeError(name)
        return getattr(_facade_model(self), name)

    def __setattr__(self, name: str, value: object) -> None:
        if _package_attribute(self, name):
            super().__setattr__(name, value)
        else:
            setattr(_facade_model(self), name, value)

    def __delattr__(self, name: str) -> None:
        if _package_attribute(self, name):
            super().__delattr__(name)
        else:
            delattr(_facade_model(self), name)


def _facade_model(module: ModuleType) -> ModuleType:
    """Import the implementation normally, including on the first model patch."""
    return importlib.import_module(
        ModuleType.__getattribute__(module, "__dict__")["_legacy_target"]
    )


def _package_attribute(module: ModuleType, name: str) -> bool:
    """Keep metadata and real child names on the package without importing them."""
    return name.startswith("__") or importlib.machinery.PathFinder.find_spec(
        f"{module.__name__}.{name}", module.__path__
    ) is not None


def configure_facade(package: str, target: str) -> None:
    """Give a domain package lazy read/write access to its canonical implementation."""
    module = sys.modules[package]
    ModuleType.__getattribute__(module, "__dict__")["_legacy_target"] = target
    module.__class__ = _Facade


FACADES = {old: new for old, new in ALIASES.items() if new.startswith(old + ".")}


def _aliased_child(fullname: str) -> str | None:
    """Map an unlisted child of an aliased old package to its canonical child."""
    package, _, rest = fullname.rpartition(".")
    while package and package != "fontlabapp":
        canonical = ALIASES.get(package)
        if canonical is not None and package not in FACADES:
            return f"{canonical}.{rest}"
        package, _, head = package.rpartition(".")
        rest = f"{head}.{rest}"
    return None


class _LegacyFinder(importlib.abc.MetaPathFinder):
    """Resolve old aliases; domain packages and their models import normally."""

    _fontlabapp_legacy_finder = True

    def find_spec(
        self, fullname: str, path=None, target=None
    ) -> importlib.machinery.ModuleSpec | None:
        if not fullname.startswith("fontlabapp."):
            return None
        target = ALIASES.get(fullname) if fullname not in FACADES else None
        if target is None:
            target = _aliased_child(fullname)
            # Unknown children stay ModuleNotFoundError under the name the caller used.
            try:
                if target is None or importlib.util.find_spec(target) is None:
                    return None
            except ModuleNotFoundError:  # parent is a plain module, not a package
                return None
        return importlib.util.spec_from_loader(fullname, _AliasLoader(target))


def install() -> None:
    """Install one current finder; a purge-and-reimport replaces a stale table."""
    sys.meta_path[:] = [
        f for f in sys.meta_path if not getattr(f, "_fontlabapp_legacy_finder", False)
    ]
    sys.meta_path.insert(0, _LegacyFinder())
